public static boolean validateAccountNum(
CustTable _custTable)
{
    if (!_custTable.AccountNum)
    {
        error("@JSZCustomer:CustomerAccountRequired");

        return false;
    }

    return true;
}

public static boolean validateCustGroup(
CustTable _custTable)
{
    if (!_custTable.CustGroup)
    {
        error("@JSZCustomer:CustomerGroupRequired");

        return false;
    }

    return true;
}

public static boolean validateDuplicateCustomer(
CustTable _custTable)
{
    CustTable custTable;

    select firstOnly custTable
    where custTable.AccountNum == _custTable.AccountNum
       && custTable.RecId != _custTable.RecId;

    if (custTable.RecId)
    {
        error(strFmt(
        "@JSZCustomer:CustomerAlreadyExists",
        _custTable.AccountNum));

        return false;
    }

    return true;
}

public static boolean validateDelete(
CustTable _custTable)
{
    return true;
}

public static boolean validateCustomer(
CustTable _custTable)
{
    boolean isValid = true;

    isValid = isValid &&
          JSZCustomerValidation::validateAccountNum(
              _custTable);

    isValid = isValid &&
          JSZCustomerValidation::validateCustGroup(
              _custTable);

    isValid = isValid &&
          JSZCustomerValidation::validateDuplicateCustomer(
              _custTable);

    return isValid;
}
